L7_1.m_CharScaleTime = 0.01
L7_1.m_Talk_KOREA = "샤레이드 한복판에서 벡터 변환 중이던 망원 렌즈를 저격으로 멈추게 했다는 거야?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "シャレードの真ん中でベクター変換中だった望遠レンズを狙撃で止めたっていうの？"
L7_1.m_Talk_ENG = "Are you saying you managed to stop the Zoom Lens mid-vector conversion with a sniper shot right in the middle of Charade?"
L7_1.m_Talk_TWN = "你是說在查雷德中心，靠狙擊成功阻止了望遠鏡頭的向量轉換？"
L7_1.m_Talk_SCN = "在查雷德的正中央，用狙击阻止了正在进行矢量转换的望远镜头吗？"
L7_1.m_Talk_DEU = "Are you saying you managed to stop the Zoom Lens mid-vector conversion with a sniper shot right in the middle of Charade?"
L7_1.m_Talk_FRA = "Are you saying you managed to stop the Zoom Lens mid-vector conversion with a sniper shot right in the middle of Charade?"
