L11_1.m_Pos = "R"
L11_1.m_Crash = 20
L11_1.m_Talk_KOREA = "너, 지금 제 정신이야? 잘못해서 망원 렌즈에 맞았으면, 어쩔 뻔했어?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "あんた、気は確か？　間違って望遠レンズに当たったらどうするつもりだったの？"
L11_1.m_Talk_ENG = "Are you out of your mind? What if you had missed and hit the Zoom Lens?"
L11_1.m_Talk_TWN = "你瘋了嗎？如果你射偏了打到望遠鏡頭怎麼辦？"
L11_1.m_Talk_SCN = "你疯了吗？万一打到望远镜头该怎么办？"
