L12_1.m_Bounce = L13_1
L12_1.m_Talk_KOREA = "만약 그랬으면, 샤레이드 한 구역이 지도에서 사라져 버렸을지도 모른다고!"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "シャレードのど真ん中にでっかい穴ができたかもしれないのよ！"
L12_1.m_Talk_ENG = "If that had happened, an entire section of Charade could have been wiped off the map!"
L12_1.m_Talk_TWN = "如果那樣，整個查雷德的區域可能會被徹底剷平！"
L12_1.m_Talk_SCN = "如果是那样的话，查雷德的一个区域可能已经从地图上消失了！"
L12_1.m_Talk_DEU = "If that had happened, an entire section of Charade could have been wiped off the map!"
L12_1.m_Talk_FRA = "If that had happened, an entire section of Charade could have been wiped off the map!"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@9#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 604
L13_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "DOCTOR_MAIN_NPC_NULL"
L13_1.m_Pos = "R"
L13_1.m_Crash = 20
L13_1.m_Talk_KOREA = "내가 말했잖아! 민간 피해는 최소화하라고 말이야!"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "言ったでしょ！　民間の被害は最小限にしろって！"
L13_1.m_Talk_ENG = "Didn't I tell you? Keep civilian casualties to a minimum!"
L13_1.m_Talk_TWN = "我不是告訴過你了嗎？務必將平民傷亡降到最低！"
L13_1.m_Talk_SCN = "我说过了！要把民间损失降到最低！"
L13_1.m_Talk_DEU = "Didn't I tell you? Keep civilian casualties to a minimum!"
L13_1.m_Talk_FRA = "Didn't I tell you? Keep civilian casualties to a minimum!"
L14_1 = {}
