L14_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L14_1.m_Pos = "L"
L14_1.m_Talk_KOREA = "후후, 이거 이상하구나."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "ふふ、おかしいわねえ。"
L14_1.m_Talk_ENG = "Fu fu. That's strange."
L14_1.m_Talk_TWN = "呵呵，真奇怪。"
L14_1.m_Talk_SCN = "呵呵，这有些奇怪啊。"
L14_1.m_Talk_DEU = "Fu fu. That's strange."
L14_1.m_Talk_FRA = "Fu fu. That's strange."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@11#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 604
L15_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L15_1.m_Pos = "L"
L15_1.m_Talk_KOREA = "쥐새끼는 소리에 민감하다던데, 왜 우리 쥐새끼는 말귀를 잘 못 알아들을까?"
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "ネズミは音に敏感だって言うけど、どうしてこっちのネズミは音に鈍感なのかしら。"
L15_1.m_Talk_ENG = "They say rats are sensitive to sound, so why is our little rat so bad at understanding words?"
L15_1.m_Talk_TWN = "老鼠對聲音很敏感，為什麼我們的老鼠卻這麼不聽話呢？"
L15_1.m_Talk_SCN = "听说老鼠对声音很敏感，为什么我们的小老鼠听不懂人话呢？"
L15_1.m_Talk_DEU = "They say rats are sensitive to sound, so why is our little rat so bad at understanding words?"
L15_1.m_Talk_FRA = "They say rats are sensitive to sound, so why is our little rat so bad at understanding words?"
