L18_1.m_CharScale = L19_1
L18_1.m_CharScaleTime = 0.01
L18_1.m_Talk_KOREA = "나야말로 말했잖니? 망원 렌즈가 아니라, 그걸 들고 있던 꼬맹이를 노린 거라고."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "私こそ言ったはずよ。望遠レンズではなく、それを持っていたチビちゃんを狙ったって。"
L18_1.m_Talk_ENG = "I told you, didn't I? I wasn't aiming for the Zoom Lens. I was aiming for the kid holding it."
