L19_1.m_Talk_KOREA = "그것도 일부러 크게 다치지 않게끔, 탄도를 계산해서 빗맞힌 거란다."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "しかもわざと大怪我しないように、弾道を計算して外したのよ。"
L19_1.m_Talk_ENG = "And I made sure to miss intentionally, calculating the trajectory so she wouldn't get seriously injured."
L19_1.m_Talk_TWN = "而且我特意計算了軌跡故意射偏，避免她受傷。"
L19_1.m_Talk_SCN = "而且是故意计算弹道，让子弹偏离目标，以免造成严重伤害的。"
L19_1.m_Talk_DEU = "And I made sure to miss intentionally, calculating the trajectory so she wouldn't get seriously injured."
L19_1.m_Talk_FRA = "And I made sure to miss intentionally, calculating the trajectory so she wouldn't get seriously injured."
