L20_1.m_CharScaleTime = 0.01
L20_1.m_Talk_KOREA = "그게 아니면, 지금 내가 가꾼 장미들의 실력을 의심하는 거니?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "それとも、私が育てたバラたちの腕を疑っているのかしら？"
L20_1.m_Talk_ENG = "Unless, of course, you're questioning the skill of the roses I've cultivated."
L20_1.m_Talk_TWN = "當然，除非你質疑我培育的玫瑰的技術。"
L20_1.m_Talk_SCN = "如果不是这样，那你是在怀疑我培养的玫瑰们的实力吗？"
L20_1.m_Talk_DEU = "Unless, of course, you're questioning the skill of the roses I've cultivated."
L20_1.m_Talk_FRA = "Unless, of course, you're questioning the skill of the roses I've cultivated."
