L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@16#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 604
L23_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_LAUGH"
L23_1.m_CharStrID = "DOCTOR_MAIN_NPC_NULL"
L23_1.m_Pos = "R"
L23_1.m_Crash = 10
L23_1.m_Talk_KOREA = "네가 가꾼 장미? 허! 아주 웃기고 자빠졌네……!"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "あんたが育てたバラ？　は！　笑わせないで……！"
L23_1.m_Talk_ENG = "The roses you cultivated? Ha! That's ridiculous...!"
L23_1.m_Talk_TWN = "你培育的玫瑰？哈！荒謬……"
L23_1.m_Talk_SCN = "你培养的玫瑰？哼！真是笑死人了！"
L23_1.m_Talk_DEU = "The roses you cultivated? Ha! That's ridiculous...!"
L23_1.m_Talk_FRA = "The roses you cultivated? Ha! That's ridiculous...!"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@17#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 604
L24_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "DOCTOR_MAIN_NPC_NULL"
L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "역시 범죄자는 사고방식이 다른 가봐? 양심이 있다면 말은 똑바로 하는 게 어때?"
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "さすがに犯罪者は考え方が普通と違うみたいね？　良心ってものがあるなら正直に言ったらどう？"
L24_1.m_Talk_ENG = "Guess criminals really do think differently. If you had any conscience, you'd speak more honestly."
L24_1.m_Talk_TWN = "看來罪犯果然思維不同。如果你有點良心，說話會誠實一點。"
L24_1.m_Talk_SCN = "果然罪犯的思维方式就是不一样啊。你能不能摸着自己的良心说？"
L24_1.m_Talk_DEU = "Guess criminals really do think differently. If you had any conscience, you'd speak more honestly."
L24_1.m_Talk_FRA = "Guess criminals really do think differently. If you had any conscience, you'd speak more honestly."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@18#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 604
L25_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_SERIOUS"
L25_1.m_CharStrID = "DOCTOR_MAIN_NPC_NULL"
L25_1.m_Pos = "R"
L25_1.m_Talk_KOREA = "그건 알파트릭스의 유산을 멋대로 훔쳐다 쓰고 있을 뿐이잖아?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "アルファトリックスの遺産を勝手に盗んで使っているだけだって。"
L25_1.m_Talk_ENG = "You're just stealing Alphatrix's legacy and using it for your own purposes."
L25_1.m_Talk_TWN = "你不過是在偷用阿爾法崔克斯的遺產，拿來為自己謀利。"
L25_1.m_Talk_SCN = "你不过是在随意窃取阿尔法崔克斯的遗产罢了。"
L25_1.m_Talk_DEU = "You're just stealing Alphatrix's legacy and using it for your own purposes."
L25_1.m_Talk_FRA = "You're just stealing Alphatrix's legacy and using it for your own purposes."
