L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@19#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 604
L27_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_DESPAIR"
L27_1.m_CharStrID = "DOCTOR_MAIN_NPC_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "자기 성과도 아닌 걸, 부풀려서 말하면 부끄럽지도 않아?"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "自分の成果でもないのに、そんなことを言って恥ずかしくないの？"
L27_1.m_Talk_ENG = "Aren't you ashamed to claim something that's not even your own work?"
L27_1.m_Talk_TWN = "不是自己的成績，卻誇大其詞地說出來，不覺得羞愧嗎？"
L27_1.m_Talk_SCN = "不是自己的成绩，却夸大其词地说出来，不觉得羞愧吗？"
L27_1.m_Talk_DEU = "Aren't you ashamed to claim something that's not even your own work?"
L27_1.m_Talk_FRA = "Aren't you ashamed to claim something that's not even your own work?"
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@20#Talk"
L28_1.m_CutScenProcessKey = 28
