L28_1.m_Pos = "C"
L28_1.m_Crash = 10
L28_1.m_Talk_KOREA = "그것도 그런 말도 안 되는 미친 기술을……!"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "しかも、あんなマッドサイエンス……！"
L28_1.m_Talk_ENG = "Especially when it's some insane technology like that...!"
L28_1.m_Talk_TWN = "尤其這還是什麼瘋狂科技……"
L28_1.m_Talk_SCN = "而且还是那种不像话的疯狂的技术！"
L28_1.m_Talk_DEU = "Especially when it's some insane technology like that...!"
L28_1.m_Talk_FRA = "Especially when it's some insane technology like that...!"
