L31_1 = {}
L31_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@21#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 604
L31_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
L31_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L31_1.m_Pos = "L"
L31_1.m_Talk_KOREA = "후후, 구 관리국의 공학자 출신이라고 해도, 역시 자기 분야가 아니면 문외한인가 보네."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "ふふ、旧管理局の工学者出身とはいっても、専門分野以外は何もわかっていないみたいね。"
L31_1.m_Talk_ENG = "Fu fu. Even if you were a former engineer of the Old Administration, I guess you're clueless when it's not your field."
L31_1.m_Talk_TWN = "呵呵。即使你曾是舊管理局的工程師，別的領域你還真是一竅不通。"
L31_1.m_Talk_SCN = "呵呵，虽然是旧管理局的工程师出身，但果然不是自己的领域就一窍不通呢。"
L31_1.m_Talk_DEU = "Fu fu. Even if you were a former engineer of the Old Administration, I guess you're clueless when it's not your field."
L31_1.m_Talk_FRA = "Fu fu. Even if you were a former engineer of the Old Administration, I guess you're clueless when it's not your field."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@22#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 604
L32_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L32_1.m_Pos = "L"
L32_1.m_Talk_KOREA = "그 도박꾼이 남긴 클론은 엄연한 실패작이었단다."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "あのギャンブラーが残したクローンは失敗作だったわ。"
L32_1.m_Talk_ENG = "The clones left behind by that degenerate were nothing but failures."
L32_1.m_Talk_TWN = "那個墮落者留下的克隆人不過是失敗品。"
L32_1.m_Talk_SCN = "那个赌徒留下的克隆品显然是个失败品。"
L32_1.m_Talk_DEU = "The clones left behind by that degenerate were nothing but failures."
L32_1.m_Talk_FRA = "The clones left behind by that degenerate were nothing but failures."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@23#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 604
L33_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L33_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L33_1.m_Talk_KOREA = "꽃의 품종이 뛰어날 뿐, 그 꽃을 가꿀 주인이 엉망이었으니까 말이지."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "優れていたのは花の品種だけで、その花を育てる主がクズなんだもの。"
L33_1.m_Talk_ENG = "The flowers were splendid, but the gardener was a mess."
L33_1.m_Talk_TWN = "花朵再美，園丁卻一團糟。"
L33_1.m_Talk_SCN = "虽然花的品种优良，但养花的主人却一团糟。"
L33_1.m_Talk_DEU = "The flowers were splendid, but the gardener was a mess."
L33_1.m_Talk_FRA = "The flowers were splendid, but the gardener was a mess."
