L36_1 = {}
L36_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@24#Talk"
L36_1.m_CutScenProcessKey = 36
L36_1.m_CutScenID = 604
L36_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L36_1.m_Talk_KOREA = "아무리 색과 향이 화려하다고 하더라도, 일찍 시들어 버린다면 가치가 없는 법이지."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "いくら色と香りが華麗だとしても、すぐに枯れてしまっては価値なんてない。"
L36_1.m_Talk_ENG = "No matter how vibrant the colors or how fragrant the scent, a flower that wilts too soon is worthless."
L36_1.m_Talk_TWN = "不管顏色多鮮豔，香味多芬芳，枯萎太早的花就是沒價值。"
L36_1.m_Talk_SCN = "无论色彩多么绚丽，多么香气扑鼻，如果过早凋谢，那就没有价值了。"
L36_1.m_Talk_DEU = "No matter how vibrant the colors or how fragrant the scent, a flower that wilts too soon is worthless."
L36_1.m_Talk_FRA = "No matter how vibrant the colors or how fragrant the scent, a flower that wilts too soon is worthless."
L37_1 = {}
L37_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE2@25#Talk"
L37_1.m_CutScenProcessKey = 37
L37_1.m_CutScenID = 604
L37_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE2"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L38_1 = "갬블러는 그깟 복수에 미쳐 자기가 가진 꽃을 가꾸는 데 소홀했지만, 나는 다르거든."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ギャンブラーは復讐に夢中で、自分の花の世話を疎かにしたけれど、私は違う。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Gambler was too obsessed with revenge to properly tend to the flowers he had. But I'm different."
L37_1.m_Talk_ENG = L38_1
L38_1 = "賭徒太迷戀復仇，無法好好照顧他培育的花。但我不同。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "赌徒因为沉迷于复仇而忽视了自己拥有的花朵，但我不一样。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Gambler was too obsessed with revenge to properly tend to the flowers he had. But I'm different."
