L41_1 = "맨션은 대를 거쳐서 오랫동안 존재해 왔고, 나는 한평생을 정원의 주인으로 살아왔단다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "マンションは古くから代を重ねて存在してきたし、私は一生を庭の主として生きてきた。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "The Mansion has existed for generations, and I have spent my entire life as the master of the garden."
L40_1.m_Talk_ENG = L41_1
L41_1 = "曼森已經存在了許多年，而我我一生都作為花園的主人生活著。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "曼森已经存在了许多年，而我我一生都作为花园的主人生活着。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "The Mansion has existed for generations, and I have spent my entire life as the master of the garden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "The Mansion has existed for generations, and I have spent my entire life as the master of the garden."
L40_1.m_Talk_FRA = L41_1
