L42_1 = "싹을 알아보고, 꽃을 피우는 법, 꽃이 오랫동안 시들지 않도록 가꾸는 법……."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "芽を見分け花を咲かせる方法、花が長い時間枯れないように世話をする方法……"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I know how to spot a sprout, how to make it bloom, and how to keep it from withering too soon..."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我知道如何辨認幼芽，如何讓它盛開，如何避免它早早凋零…"
L41_1.m_Talk_TWN = L42_1
L42_1 = "识别幼苗，培育花朵，让花长久不凋谢的方法……"
L41_1.m_Talk_SCN = L42_1
L42_1 = "I know how to spot a sprout, how to make it bloom, and how to keep it from withering too soon..."
L41_1.m_Talk_DEU = L42_1
L42_1 = "I know how to spot a sprout, how to make it bloom, and how to keep it from withering too soon..."
L41_1.m_Talk_FRA = L42_1
