L44_1 = "그리고 설령, 시들어 버릴지라도 그 가치를 잃지 않게 만드는 법을 알고 있지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "たとえ枯れてしまっても、その価値を失わなずに済む方法を知っているわ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "And even if it does wither, I know how to ensure it never loses its value."
L43_1.m_Talk_ENG = L44_1
L44_1 = "即使凋零，我也知道怎麼確保它永不失去價值。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "即便是枯萎，也有不让它失去价值的方法。"
