L45_1 = "그러니까 저 애들은 나를 만나, 비로소 꽃이 될 수 있는 거란다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "だからあの子たちは私に出会って、やっと花になれるの。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "So those children could only truly become flowers after meeting me."
L44_1.m_Talk_ENG = L45_1
L45_1 = "因此，那些孩子只有遇到我後才能真正成為花朵。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "所以那些孩子们遇到我，才能真正绽放成花朵啊。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "So those children could only truly become flowers after meeting me."
