L48_1 = "그리고 프로젝트 오즈를 통해, 임상 테스트를 마친 사고 공유 시스템……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "そしてプロジェクト・オズを経て、臨床テストを終えた思考共有システム……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "And with the clinical testing of the thought-sharing system completed through Project OZ..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "在經過奧茲國計畫完成的思維共享系統臨床測試後…"
L47_1.m_Talk_TWN = L48_1
L48_1 = "通过奥兹计划，完成临床测试的思维共享系统……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "And with the clinical testing of the thought-sharing system completed through Project OZ..."
