L48_1.m_CharStrID = "MASTER_NPC_MANSION_NULL"
L49_1 = "<color=#ffd34c>하우스홀드</color> 네트워크는 저 아이들을 점점 더 완벽에 가까운 꽃으로 성장시켜 줄 테지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "<color=#ffd34c>ハウスホールド</color>ネットワークはあの子たちをますます完璧に近い花に成長させてくれるはずよ。"
L48_1.m_Talk_JPN = L49_1
