L2_1 = "결국에는 나를 떠나버린 그 아이보다도 훨씬 더 아름답게 피어날 거야."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そして、私から離れていったあの子よりもずっと美しく咲くの。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Eventually, they will bloom far more beautifully than that kid who left me."
L1_1.m_Talk_ENG = L2_1
L2_1 = "終有一天，她們會盛開得比離開我的那個孩子更美麗。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "最终，会比那个离开我的孩子绽放地更加美丽。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Eventually, they will bloom far more beautifully than that kid who left me."
L1_1.m_Talk_DEU = L2_1
