L14_1.m_Pos = "L"
L15_1 = "쓸데없는 도덕과 관습에 묶여, 남들보다 뒤처질 바엔, 할 수 있는 걸 하는 편이 낫지."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "つまらない道徳と慣習に捉われて出遅れるよりは、私にできることをしたまでよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Better to do what you can than to cling to pointless morals and conventions and fall behind."
L14_1.m_Talk_ENG = L15_1
L15_1 = "做你能做的，總比固守毫無意義的道德和慣例、被落在後面來得好。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "与其被无用的道德和习俗束缚，落后于人，不如做自己能做的事情。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Better to do what you can than to cling to pointless morals and conventions and fall behind."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Better to do what you can than to cling to pointless morals and conventions and fall behind."
