L16_1 = "관리 실패 이후 줄곧 쥐구멍에 틀어박혀 있던 어느 쥐새끼랑은 다르게 말이야."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "管理失敗以後、ずっと狭い穴に閉じこもっていたネズミとは違ってね。"
