L18_1 = "글쎄? 애초에 나는 쥐새끼, 네가 뭘 그리 깨끗한 척 구는지 도통 이해가 안 되거든."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "さあね。そもそも私はね、ネズミ。あなたが綺麗事を言っているのが理解できないの。"
