L18_1 = "Who knows? I just don't get why a rat like you is acting so holier-than-thou."
L17_1.m_Talk_ENG = L18_1
L18_1 = "誰知道？我就是不懂為什麼她這種老鼠裝得這麼道貌岸然。"
L17_1.m_Talk_TWN = L18_1
