L23_1.m_CharScale = L24_1
L23_1.m_CharScaleTime = 0.01
L24_1 = "그럼, 애초부터 그 대단하신 구 관리국의 영웅분들께서 세계를 지켜냈다면 좋았을 것을."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "だったら最初からそのお偉い旧管理局の英雄たちが世界を守っていればよかったのよ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "If those great heroes of the Old Administration had managed to protect the world in the first place, we wouldn't be in this mess."
L23_1.m_Talk_ENG = L24_1
L24_1 = "如果舊管理局那些大英雄一開始能守護世界，我們就不會落得這種局面。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "那最初就应该让那些伟大的旧管理局英雄们来保护世界。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "If those great heroes of the Old Administration had managed to protect the world in the first place, we wouldn't be in this mess."
L23_1.m_Talk_DEU = L24_1
L24_1 = "If those great heroes of the Old Administration had managed to protect the world in the first place, we wouldn't be in this mess."
L23_1.m_Talk_FRA = L24_1
