L25_1 = "그래서? 누구 때문에 세계가 이 꼴이 됐는데, 그 패배자들은 어디 처박혀 있는 거니?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "それで？　誰かさんのせいで世界がこの様なのに、その負け犬どもはどこに隠れてるのかしらね？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "So, tell me. Who's responsible for this world being in such a state, and where are those so-called heroes hiding now?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "那告訴我，這世界變成這樣是誰的責任，那些所謂英雄現在藏哪裡？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "所以呢？是谁让世界变成这样的，那些失败者都躲在哪里了？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "So, tell me. Who's responsible for this world being in such a state, and where are those so-called heroes hiding now?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "So, tell me. Who's responsible for this world being in such a state, and where are those so-called heroes hiding now?"
