L34_1 = "SYSOP_MAIN_NPC_QM"
L33_1.m_CharStrID = L34_1
L34_1 = "자네들은 서로 입장이 다르지. 어차피 언쟁을 계속해 봤자, 서로 감정만 상하게 될 뿐이라네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "君たちは立場が違うんだ。言い争っても、お互い傷つくだけさ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You two come from different perspectives. Continuing this argument will only hurt your feelings."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你們來自不同立場，繼續爭吵只會傷感情。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "你们的立场不同。继续争论下去，只会互相伤害。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "You two come from different perspectives. Continuing this argument will only hurt your feelings."
L33_1.m_Talk_DEU = L34_1
L34_1 = "You two come from different perspectives. Continuing this argument will only hurt your feelings."
