L34_1.m_Pos = "R"
L35_1 = "시끄러워, 깡통. 넌 지금 몇 신 줄 알아?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "うるさい、ボロ缶。今何時だと思ってるの？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Shut up, Tin Can. Do you even know what time it is right now?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "閉嘴，鐵罐。你知道現在幾點了嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "闭嘴，铁罐头。你知道现在几点了吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Shut up, Tin Can. Do you even know what time it is right now?"
L34_1.m_Talk_DEU = L35_1
