L35_1.m_Pos = "R"
L36_1 = "기계 주제에 시간 감각이 없는 것 같은데, 그 잘난 머리통에 시계라도 박아줄까?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "機械のくせに時間の感覚がないみたいだけど、その偉そうな頭に時計でも埋め込んであげようか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "For a machine, your sense of time seems pretty messed up. Want me to implant a clock in that fancy head of yours?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "身為機械，你的時間觀念還真糟糕。要我給你裝個時鐘嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "你这个机器好像没有时间观念啊，要不要在你那聪明的脑袋里装个时钟？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "For a machine, your sense of time seems pretty messed up. Want me to implant a clock in that fancy head of yours?"
L35_1.m_Talk_DEU = L36_1
