L38_1 = "SYSOP_MAIN_NPC_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "후후, 선물이라면 감사히 받겠네만, 가급적이면 손목 시계로 부탁하지, 닥터."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "ふふ。プレゼントならありがたくいただくが、なるべく腕時計で頼むよ、ドクター。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Haha. If it's a gift, I'll gladly accept it, but I'd prefer a wristwatch, Doctor."
L37_1.m_Talk_ENG = L38_1
L38_1 = "哈哈。如果是禮物，我樂意接受，不過我比較想要手錶，博士。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "呵呵，如果是礼物的话我会欣然接受，不过尽量送手表吧，博士。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Haha. If it's a gift, I'll gladly accept it, but I'd prefer a wristwatch, Doctor."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Haha. If it's a gift, I'll gladly accept it, but I'd prefer a wristwatch, Doctor."
