L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "그리고 오랜만이네, 마담. 내가 보낸 선물은 마음에 들었나?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "久しぶりだね、マダム。私からのプレゼントは気に入ってくれたかな？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It's been a while, Madam. Did you like the gift I sent you?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "好久不見，夫人。你喜歡我送的禮物嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "而且好久不见了，夫人。喜欢我送的礼物吗？"
