L42_1 = "하여간 일을 벌여 놓고 마지막에 등장하는 건 여전하구나, 애늙은이."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "事を始めておいて最後に登場するところは相変わらずね、ませガキさん。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "As usual, you show up at the end after stirring things up, you old soul."
L41_1.m_Talk_ENG = L42_1
L42_1 = "跟平常一樣，你總是在攪局後出現，少年老成。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "总是惹完麻烦，最后才出现，真是个老顽童。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "As usual, you show up at the end after stirring things up, you old soul."
L41_1.m_Talk_DEU = L42_1
