L43_1 = "뭐, 첫 실전치고는 제법 나쁘지 않았단다. 꽤나 우수한 품종의 꽃이더군."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "まあ、初実戦にしては悪くなかったわ。なかなか優秀な品種の花のようね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Still, it wasn't bad for a first field test. Quite a remarkable breed of flowers you brought."
L42_1.m_Talk_ENG = L43_1
L43_1 = "不過這次第一次實地測試還不錯。你帶來的花朵真是了不起。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "嗯，作为第一次实战来说还不错。真是相当优秀的花朵呢。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Still, it wasn't bad for a first field test. Quite a remarkable breed of flowers you brought."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Still, it wasn't bad for a first field test. Quite a remarkable breed of flowers you brought."
