L44_1 = "앞으로 어떻게 가꾸느냐에 따라, 우리의 전력이 될 수도 있겠지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "この先の育て方次第では、私たちの戦力になるかもしれないわ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Depending on how they're nurtured, they could become our valuable asset."
