L49_1.m_fTalkTime = 0.03
L50_1 = "リーグ優勝で有名にはなったけど……所詮はカウンターでもないただの人間……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "They became somewhat famous after winning the league... But they're just ordinary humans, not Counters..."
