L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "물론, 천재가 세계를 바꿀 수 있다는 건 관리국의 중요 지침 중 하나라네."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "もちろん、天才が世界を変えられるというのは管理局の重要指針の一つだ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Of course, one of the core principles of the Administration is that geniuses can change the world."
L3_1.m_Talk_ENG = L4_1
L4_1 = "當然，管理局的一個核心原則是天才能改變世界。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "当然，天才能够改变世界是管理局的重要指示之一。"
