L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L5_1 = "그리고 자네들은 각자의 분야에서 천재성을 드러낸 이들."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そして、君たちは各々の分野で天才的な才能を見せていた。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You all have shown genius in your respective fields."
L4_1.m_Talk_ENG = L5_1
L5_1 = "你們各自在所屬領域都有天賦。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "而你们则是在各自领域中展现出天才般的才华的人。"
