L19_1 = "빙빙 돌려서 말할 필요 없단다. 어차피 미쳐버린 네 사상 따위는 전혀 관심 없으니까."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "遠回しに言う必要はないわ。どうせ狂ったあなたの思想なんて、まったく興味ないもの。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "There's no need for all this roundabout talk. I'm not interested in your crazy philosophy."
L18_1.m_Talk_ENG = L19_1
L19_1 = "別繞圈子了，我對你那瘋狂哲學沒興趣。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "没必要绕圈子说话。反正我对你那疯狂的思想毫无兴趣。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "There's no need for all this roundabout talk. I'm not interested in your crazy philosophy."
L18_1.m_Talk_DEU = L19_1
