L14_1 = "맞아, 내가 구해준 건 잊지 않았겠지? 이번 건은 대충 쌤쌤으로 퉁치자고."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そうだ、助けてやったこと、忘れてないよね？　今回のはおあいこってことで。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "And don't forget I saved you back there. Let's just call it even for now."
L13_1.m_Talk_ENG = L14_1
L14_1 = "別忘了我還救過你。現在算扯平了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "对了，你不会忘记我救过你吧？这次的事情就算扯平了吧。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "And don't forget I saved you back there. Let's just call it even for now."
L13_1.m_Talk_DEU = L14_1
