L16_1 = "그러고 보니… 그 마스터라는 사람은 누구예요? 아는 사이 같던데……?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "そういえば……あのマスターって人は誰なの？　知り合いみたいだったけど……？"
