L9_1 = "그리고 평의회라고? 그럼, 설마 우리를 납치한 게 검은 평의회라는 뜻이야?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "それに評議会？　じゃあ、私たちを拉致したのは黒い評議会ってこと？"
