L10_1 = "웃기지 마. 평의회 정도 되는 거물이 우리 같은 피라미를 왜 납치하겠어?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "笑わせるなよ。評議会ほどの大物がなんで私たちみたいな雑魚を拉致するんだ？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Don't make me laugh. Why would a big shot organization like the Council bother kidnapping nobodies like us?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "別鬧了。評議會這種大組織幹嘛綁架我們這種無名小卒？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "别开玩笑了。像评议会那样的大人物为什么要绑架我们这些小鱼小虾？"
