L14_1.m_CharScale = L15_1
L14_1.m_CharScaleTime = 0.01
L15_1 = "과격한 방식이었다면 사과하지. 나는 어디까지나 자네들을 손님으로서 이곳에 초청했다네."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "やり方が過激だったのなら謝罪しよう。私はあくまでも君たちを客人としてここに招待したんだ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "If things got rough, I apologize. I only intended to invite you as guests."
L14_1.m_Talk_ENG = L15_1
L15_1 = "如果起了衝突，我道歉。我只是想邀請你們做客而已。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "如果我的方式过于激烈，我向你们道歉。我只是把你们当作客人邀请到这里来。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "If things got rough, I apologize. I only intended to invite you as guests."
L14_1.m_Talk_DEU = L15_1
