L15_1.m_CharScale = L16_1
L15_1.m_CharScaleTime = 0.01
L16_1 = "왜냐하면 자네들은 작고 미약한 존재지만, 동시에 이 세계를 바꿀 수도 있는 변수거든."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "なぜなら君たちは小さく弱い存在だが、同時にこの世界を変え得る変数だからだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "After all, though you may be small and insignificant, you also hold the variable to change the world."
L15_1.m_Talk_ENG = L16_1
L16_1 = "畢竟，你們雖小且無足輕重，但同時也是改變世界變量。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "因为你们虽然渺小而微弱，但同时也是能够改变这个世界的变量。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "After all, though you may be small and insignificant, you also hold the variable to change the world."
L15_1.m_Talk_DEU = L16_1
