L18_1.m_Crash = 20
L19_1 = "손님 좋아하시네! 요즘은 환영 인사로 생사람 어깨를 뽑냐? 아직도 욱씬 거리거든?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "客人！？　最近は歓迎のあいさつで人の肩を外したりするのか？　まだずきずきするんだけど。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Guests? Oh yeah? Since when do you greet guests by dislocating their shoulders? It still hurts, you know!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "客人？從什麼時候起招待客人會扭斷肩膀？我還在痛呢！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "当作客人？现在的欢迎仪式是卸胳膊吗？现在还隐隐作痛呢。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Guests? Oh yeah? Since when do you greet guests by dislocating their shoulders? It still hurts, you know!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Guests? Oh yeah? Since when do you greet guests by dislocating their shoulders? It still hurts, you know!"
L18_1.m_Talk_FRA = L19_1
