L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "L"
L21_1 = "그렇다면, 저번처럼 이 세계에 무슨 위험한 일이 또 발생할지도 모른다는 건가요?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "それって、この前のようにこの世界に何か危険なことがまた発生するかもしれないということですか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Does that mean something dangerous is going to happen in this world again, like last time?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "那是不是又要在這世界發生什麼危險事件，像上次一樣？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "那么，那是不是意味着又会像上次一样，这个世界可能会发生什么危险的事情呢？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Does that mean something dangerous is going to happen in this world again, like last time?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Does that mean something dangerous is going to happen in this world again, like last time?"
