L33_1 = "그것은 인류사의 분기점마다 출몰하여, 인류를 시험하는 존재. 클리포트의 마왕이라네."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それは人類史の分岐点ごとに現れ、人類を試す存在。クリフォトの魔王だ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It's an entity that appears at critical junctures in human history to test humanity. A Demon Lord of Qliphoth."
