L33_1 = "他在人類歷史的關鍵時刻出現，考驗人類，是逆卡巴拉魔王。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "那是在人类历史的分岔点出现，考验人类的存在。神圣魔王。"
