L43_1 = "다행히 저것의 존재를 알고 있는 아버지께서도 안배를 해두시겠지만, 결과적으로는 한걸음이 부족하겠지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
