L51_1 = "이 소체에 동맥 같은 건 존재하지 않아. 자네들처럼 따뜻한 피가 흐르지 않는다는 뜻이지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "この素体に動脈など存在しない。君たちのように暖かい血は流れていないというわけだ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "This body has no arteries. There's no warm blood flowing through it like yours."
L50_1.m_Talk_ENG = L51_1
L51_1 = "這個軀體中不存在動脈。也就是說，不會像你們一樣有溫熱的血液流動。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "这个躯体中不存在动脉。也就是说，不会像你们一样有温热的血液流动。"
