L2_1 = "따라서 나에게 자네들의 주관적인 감정의 잣대를 들이대 봤자, 곤란할 뿐이라네."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だから君たちの主観的な感情の基準を押しつけられても、困ってしまうんだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "So using your subjective standards of emotion against me is pointless."
L1_1.m_Talk_ENG = L2_1
L2_1 = "因此，即使你們用主觀的情感標準來衡量我，也只會讓事情變得困難。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "因此，即使你们用主观的情感标准来衡量我，也只会让事情变得困难。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "So using your subjective standards of emotion against me is pointless."
L1_1.m_Talk_DEU = L2_1
L2_1 = "So using your subjective standards of emotion against me is pointless."
L1_1.m_Talk_FRA = L2_1
