L7_1.m_Talk_JPN = L8_1
L8_1 = "Now then, let's get back to the subject. You asked why I chose you two, correct?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "我們回到正題。問我為什麼選擇你們嗎？"
L7_1.m_Talk_TWN = L8_1
