L8_1.m_CharScale = L9_1
L8_1.m_CharScaleTime = 0.01
L9_1 = "내가 자네들을 선택한 이유는 세계가 변하면서, 자네들이 소중한 것을 잃어버렸기 때문이야."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私が君たちを選んだ理由は世界が変化し、君たちが大切なものを失ったからだ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I chose you because, after the world changed, you lost something precious."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我選擇你們的原因是因為隨著世界的變化，你們失去了珍貴的東西。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "我选择你们的原因是因为随着世界的变化，你们失去了珍贵的东西。"
