L6_1 = "갑작스럽게 세계가 바뀌고, 정보가 갱신된다 해도, 인간의 인식은 그 속도를 따라잡지 못하는 경우가 있거든."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "突然世界が変化して情報が更新されても、人間の認識はそのスピードに追い付けない場合がある。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "When the world suddenly changes and information is updated, the human mind can't always keep up."
L5_1.m_Talk_ENG = L6_1
L6_1 = "即使世界突然改變，資訊更新，人類的認知也可能跟不上這種速度。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "即使世界突然改变，信息更新，人类的认知也可能跟不上这种速度。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "When the world suddenly changes and information is updated, the human mind can't always keep up."
L5_1.m_Talk_DEU = L6_1
