L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "R"
L36_1 = "처음에는 당연히 유미나 얘기인 줄 알았는데, 곰곰이 생각해 보니까 역시 아닌 것 같아."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "最初は当然ミナのことだろうと思ったけど、よく考えてみたらやっぱりなんか変。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "At first, I thought he was talking about Yoo Mina. But the more I think about it, that's not it."
L35_1.m_Talk_ENG = L36_1
L36_1 = "一開始我以為是在說劉米娜，但仔細想想，似乎不是這樣。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "一开始我以为是在说刘米娜，但仔细想想，似乎不是这样。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "At first, I thought he was talking about Yoo Mina. But the more I think about it, that's not it."
L35_1.m_Talk_DEU = L36_1
L36_1 = "At first, I thought he was talking about Yoo Mina. But the more I think about it, that's not it."
