L37_1 = "LAIKA_CANARY_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "R"
L37_1 = "분명히 우리 중에 누군가… 카나리아 스쿼드에 누군가가 한 명이 더 있었어……."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "きっと私たちの中に……カナリア・スクワッドに誰かもう1人いたんだ……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "There was definitely someone else among us... someone in Canary Squad..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "肯定是我們中的某個人……金絲雀小隊裡還有一個人……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "肯定是我们中的某个人……金丝雀小队里还有一个人……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "There was definitely someone else among us... someone in Canary Squad..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "There was definitely someone else among us... someone in Canary Squad..."
