L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "이름과 얼굴이 떠오르지는 않지만… 틀림없이 기억 속에 그 아이는 웃고 있었어요……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "名前と顔は思い出せないけど……確かに記憶の中のその子は笑ってた……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I can't remember her name or face, but... I remember her smiling..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "雖然名字和臉龐已經模糊不清……但在記憶中，那孩子一定是在微笑著……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "虽然名字和脸庞已经模糊不清……但在记忆中，那孩子一定是在微笑着……"
