L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "이 땅에 강림한 세피라의 힘이 사라지면서 자네들은 소중한 누군가를 잃게 되었어."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "この地に降臨したセフィラの力が消え、君たちは大切な誰かを失うことになった。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "When Sephira's power descended upon this land and then vanished, you lost someone precious."
L42_1.m_Talk_ENG = L43_1
L43_1 = "隨著降臨此地的生命樹之力消失，你們失去了某個珍貴的人。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "随着降临此地的塞菲拉之力消失，你们失去了某个珍贵的人。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "When Sephira's power descended upon this land and then vanished, you lost someone precious."
