L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "그리고 방금까지 그것을 잃었다는 사실조차 망각하고 있었지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "そして今までそれを失ったことさえも忘れていた。"
