L48_1.m_Pos = "C"
L49_1 = "하지만 사람과 사람 사이에 깊게 맺어진 인연은 그리 단순하게 지울 수 있는 게 아니야."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だが、人と人の間に結ばれた深い絆はそう簡単に消せるものではない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "But bonds deeply tied between people aren't so easily erased."
L48_1.m_Talk_ENG = L49_1
L49_1 = "但是人與人之間深厚的緣分並不是那麼簡單就能抹去的。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "但是人与人之间深厚的缘分并不是那么简单就能抹去的。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "But bonds deeply tied between people aren't so easily erased."
L48_1.m_Talk_DEU = L49_1
L49_1 = "But bonds deeply tied between people aren't so easily erased."
L48_1.m_Talk_FRA = L49_1
