L50_1 = "SYSOP_MAIN_NPC_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "그리고 때때로 인연이라는 건, 기적을 만들어내기도 하지."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そして時に絆とは、奇跡を生み出すこともある。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "And sometimes, those bonds can even create miracles."
L49_1.m_Talk_ENG = L50_1
L50_1 = "有時候，緣分也會創造奇蹟。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "有时候，缘分也会创造奇迹。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "And sometimes, those bonds can even create miracles."
L49_1.m_Talk_DEU = L50_1
L50_1 = "And sometimes, those bonds can even create miracles."
